private object PatchEventSinkHandleMap {
    private val map = java.util.concurrent.ConcurrentHashMap<Long, PatchEventSink>()
    private val counter = java.util.concurrent.atomic.AtomicLong(1L)

    fun insert(obj: PatchEventSink): Long {
        val handle = counter.getAndAdd(2L)
        map[handle] = obj
        return handle
    }

    fun get(handle: Long): PatchEventSink? = map[handle]

    fun remove(handle: Long): PatchEventSink? = map.remove(handle)

    fun clone(handle: Long): Long {
        val obj = map[handle] ?: return 0L
        return insert(obj)
    }
}

