    @JvmStatic
    fun free(handle: Long) {
        PatchEventSinkHandleMap.remove(handle)
    }

    @JvmStatic
    fun clone(handle: Long): Long {
        return PatchEventSinkHandleMap.clone(handle)
    }

    @JvmStatic
    fun on_event(handle: Long, eventJson: ByteBuffer) {
        val impl = PatchEventSinkHandleMap.get(handle) ?: error("PatchEventSinkHandleMap: invalid handle $handle")
